const fs = require('fs');
const b = JSON.parse(fs.readFileSync(process.argv[2] || 'board.json', 'utf8'));
const data = b.board || b;
const cols = data.columns || [];
const cards = data.cards || [];
const want = ['Features & Table-Stakes', 'Differentiation & Moat'];
console.log('ALL COLUMNS:', cols.map(c => `${c.name} (${cards.filter(k=>k.columnId===c.id).length})`).join(' | '));
const target = cols.filter(c => want.some(w => c.name.trim().toLowerCase() === w.toLowerCase()));
for (const col of target) {
  const cc = cards.filter(k => k.columnId === col.id).sort((a,b)=> (a.position||0)-(b.position||0));
  console.log(`\n\n########## COLUMN: ${col.name} (${cc.length} cards) ##########`);
  cc.forEach((k,i) => {
    console.log(`\n----- [${i+1}] ${k.title} -----`);
    console.log(`type=${k.type} priority=${k.priority}`);
    console.log((k.description || '(no description)').trim());
  });
}

