const fs=require('fs');
const d=JSON.parse(fs.readFileSync('board.json','utf8'));
const data=d.board||d; const cols=data.columns||[]; const cards=data.cards||[];
function dump(name,file){
  const col=cols.find(c=>c.name.trim()===name);
  const cc=cards.filter(k=>k.columnId===col.id).sort((a,b)=>(a.position||0)-(b.position||0));
  let s='COLUMN '+name+' n='+cc.length+String.fromCharCode(10);
  cc.forEach((k,i)=>{s+=String.fromCharCode(10)+'#'+(i+1)+' | '+k.title+' | '+k.type+' | '+k.priority+String.fromCharCode(10)+(k.description||'(none)').trim()+String.fromCharCode(10);});
  fs.writeFileSync(file,s);
  console.log(file,'bytes',s.length,'cards',cc.length);
}
dump('Features & Table-Stakes','colA.txt');
dump('Differentiation & Moat','colB.txt');
"
